CREATE TABLE stored_order_filter (id integer PRIMARY KEY, shop text, ord bigint, code varchar(30) COLLATE "C");
INSERT INTO stored_order_filter VALUES (1,'O''Brien',9007199254740992,'AA'),(2,'O''Brien',9007199254740993,'aa'),(3,'',-9223372036854775808,'AA'),(4,'NULL',0,''),(5,NULL,NULL,NULL),(6,'青木',9223372036854775807,'ＡＡ');
SELECT id, shop, ord FROM stored_order_filter WHERE shop = CAST('O''Brien' AS pg_catalog.text) ORDER BY id;
SELECT id, shop, ord FROM stored_order_filter WHERE shop = CAST('O''Brien' AS pg_catalog.text) AND CAST('9007199254740992' AS pg_catalog.int8) < ord ORDER BY id;
SELECT id, shop, ord FROM stored_order_filter WHERE CAST('' AS pg_catalog.varchar) = shop ORDER BY id;
SELECT id, shop, ord FROM stored_order_filter WHERE shop = CAST('NULL' AS pg_catalog.text) ORDER BY id;
SELECT id, shop, ord FROM stored_order_filter WHERE shop <> CAST('NULL' AS pg_catalog.text) ORDER BY id;
SELECT id, shop, ord FROM stored_order_filter WHERE shop = CAST(NULL AS pg_catalog.text) ORDER BY id;
SELECT id, shop, ord FROM stored_order_filter WHERE ord >= CAST('-9223372036854775808' AS pg_catalog.int8) AND ord < CAST('0' AS pg_catalog.int2) ORDER BY id;
SELECT id, shop, ord FROM stored_order_filter WHERE ord >= CAST('9223372036854775807' AS pg_catalog.int8) ORDER BY id;
SELECT id, shop, ord FROM stored_order_filter WHERE ord <= CAST('9007199254740993' AS pg_catalog.int8) AND ord >= CAST('9007199254740993' AS pg_catalog.int8) ORDER BY id;
SELECT id, shop, ord FROM stored_order_filter WHERE ord = CAST('bad' AS pg_catalog.int8) ORDER BY id;
SELECT id, shop, ord FROM stored_order_filter WHERE ord = CAST('4294967296' AS pg_catalog.int4) ORDER BY id;
