SELECT id, shop, ord FROM stored_order_filter WHERE code COLLATE "C" = CAST('aa' AS pg_catalog.text) ORDER BY id;
SELECT id, shop, ord FROM stored_order_filter WHERE shop = CAST('青木' AS pg_catalog.text) AND pg_catalog.length(shop) = 2 ORDER BY id;
SELECT id, shop, ord FROM stored_order_filter WHERE shop = CAST('NULL' AS pg_catalog.text) OR ord = CAST('9007199254740993' AS pg_catalog.int8) ORDER BY id;
BEGIN;
SAVEPOINT stored_filter_before;
UPDATE stored_order_filter SET shop = 'another' WHERE shop = CAST('O''Brien' AS pg_catalog.text) AND ord > CAST('9007199254740992' AS pg_catalog.int8);
SELECT id, shop, ord FROM stored_order_filter WHERE shop = CAST('another' AS pg_catalog.text) ORDER BY id;
ROLLBACK TO stored_filter_before;
SELECT id, shop, ord FROM stored_order_filter WHERE shop = CAST('O''Brien' AS pg_catalog.text) ORDER BY id;
COMMIT;
DELETE FROM stored_order_filter WHERE shop = CAST('NULL' AS pg_catalog.text) RETURNING id;
SELECT id, shop, ord FROM stored_order_filter WHERE ord >= CAST('0' AS pg_catalog.int4) ORDER BY id;
